<?php
declare(strict_types=1); namespace App\Http\Controllers;
use App\Application\Services\CatalogService;
final class CatalogController extends Controller { public function __construct(private CatalogService $catalog){} public function products(array $request):array{$r=$this->catalog->products($request);return $this->paginated($r['items'],$r['total'],$r['page'],$r['pageSize']);} public function product(string $productSlug):array{return $this->ok($this->catalog->product($productSlug));} public function pricing(string $skuId):array{return $this->ok($this->catalog->quote($skuId,5));} public function quote(array $data):array{return $this->ok($this->catalog->quote((string)($data['skuId']??''),(int)($data['quantity']??0)));} public function series():array{return $this->ok($this->catalog->taxonomy('series'));} public function publishers():array{return $this->ok($this->catalog->taxonomy('publishers'));} public function categories():array{return $this->ok($this->catalog->taxonomy('categories'));} }
